{"sql": "-- First, let's see some actors who worked with Yash Chopra and count their collaborations
WITH yc_films AS (
    SELECT DISTINCT MID FROM M_Director WHERE PID = 'nm0007181'
),
yc_actors AS (
    SELECT DISTINCT mc.PID 
    FROM M_Cast mc
    JOIN yc_films yf ON mc.MID = yf.MID
)
SELECT COUNT(*) as num_actors_with_yc FROM yc_actors"}

